import json,unittest
from core import document_rendering as r, document_renderer_contract as c
from tests.support import document_renderer_fixtures as f
from tests.support.document_renderer_fake import FakeRenderer
class Probe(unittest.TestCase):
 def probe(self,release_delay,result_delay,want):
  now=[0];worker=FakeRenderer();events=[]
  req=c.make_request(job_id=f.JOB,revision_id=f.REVISION,canonical=f.canonical(),canonical_sha256=c.digest(c.json_bytes(f.canonical())),format='docx',engine=f.ENGINE)
  session=r.RenderingSession(client=worker,expected_engine=f.ENGINE,monotonic=lambda:now[0],wait=lambda:None)
  release=worker.cancel_release;result=worker.result
  def fetched(request):now[0]+=result_delay;return result(request)
  def released(request,*,cancel=False):
   if not cancel:now[0]+=release_delay
   ack=release(request,cancel=cancel);c.validate_release_message(ack,request=request,cancel=cancel);events.append('cancel_ack' if cancel else 'release_ack');return ack
  worker.result=fetched;worker.cancel_release=released
  try:session.collect(req,check=lambda:None);decision='success'
  except c.RendererError as e:decision=e.reason_code
  print(json.dumps(dict(release_delay=release_delay,result_delay=result_delay,decision=decision,events=worker.events,acks=events,collected=session.collected is not None,cached=session._released is not None,executions=worker.executions,active=worker.active is not None)),flush=True)
  self.assertEqual(decision,want)
 def test_nominal(self):self.probe(0,0,'success')
 def test_release_before_limit(self):self.probe(119.999,0,'success')
 def test_release_at_limit(self):self.probe(120,0,'renderer_inactivity')
 def test_result_at_limit(self):self.probe(0,120,'renderer_inactivity')
unittest.main(verbosity=2)

